        _builder: &dyn ToolBuilder,
        _changed_uri: &Uri,
        _root_uri: &Uri,
        _options: serde_json::Value,
    ) -> ToolRestartChanges {
        ToolRestartChanges { tool: None, watch_patterns: None }
    }
    fn run_format(&self, document: &TextDocument) -> Result<Vec<TextEdit>, String> {
        let text = document.text.as_deref().unwrap_or("");
        if text == "const x=1" {
            return Ok(vec![TextEdit {
                range: Range::new(Position::new(0, 0), Position::new(0, text.len() as u32)),
                new_text: "const x = 1;".to_string(),
            }]);
        }
        Ok(vec![])
    }
    fn run_diagnostic(&self, document: &TextDocument) -> DiagnosticResult {
        Ok(vec![(document.uri.clone(), vec![Diagnostic { message: "diag".into(), ..Default::default() }])])
    }
}

struct FmtBuilder;
impl ToolBuilder for FmtBuilder {
    fn build_boxed(&self, _root_uri: &Uri, _options: serde_json::Value) -> Box<dyn Tool> {
        Box::new(FmtTool)
    }
    fn server_capabilities(&self, _c: &mut ServerCapabilities, _b: &mut oxc_language_server::Capabilities) {}
}

