///
/// A single dynamic worker rooted at the file-system root (`file:///`) is created so
/// that requests (e.g. formatting) for files located outside the configured workspace
/// folders can still be served.
fn build_worker_manager(tool: Arc<dyn ToolBuilder>) -> WorkerManager {
    // Determine the diagnostic mode the tool wants to operate in. This mirrors what
    // happens during `initialize`, so the dynamic worker is created consistently.
    let mut capabilities = Capabilities::default();
    let mut server_capabilities = server_capabilities();
    tool.server_capabilities(&mut server_capabilities, &mut capabilities);

    // The dynamic worker targets the file-system root so it can serve any file URI that
    // is not covered by an explicit workspace worker.
    let root_uri: Uri = "file:///".parse().expect("`file:///` is a valid URI");
    let dynamic_worker =
        WorkspaceWorker::new(root_uri, Arc::clone(&tool), capabilities.diagnostic_mode);

    WorkerManager::new_with_mode(
        tool,
        ManagerMode::DynamicWithWorkspaces(Box::new(RwLock::new(dynamic_worker))),
    )
}

/// Run the language server
pub async fn run_server(server_name: String, server_version: String, tool: Arc<dyn ToolBuilder>) {
    let stdin = tokio::io::stdin();
    let stdout = tokio::io::stdout();

    let manager = build_worker_manager(tool);

    let (service, socket) = LspService::build(move |client| {
        crate::backend::Backend::new(
            client,
            ServerInfo { name: server_name, version: Some(server_version) },
            manager,
        )
    })
    .finish();

    Server::new(stdin, stdout, socket).serve(service).await;
}
